import fs from "node:fs";
import path from "node:path";
import type { ImageSet, Localized } from "./projects";

/**
 * The case-study page of one project, generated by `npm run sync` into
 * content/projects/<slug>/page.json. Section text comes from the case-study
 * Markdown (rendered to HTML at sync time), copied as written.
 */
export type CaseSection = { heading: string; kind: "plain" | "role" | "tech"; html: string };
export type CaseStudy = { title: string; lead: string; sections: CaseSection[] };
export type Shot = { name: string; device: "desktop" | "mobile"; lang: "ar" | "en" | null; caption: Localized; image: ImageSet };
export type Clip = { name: string; lang: "ar" | "en" | null; caption: Localized; mp4: string; webm: string | null; poster: ImageSet };

export type Result = { value: string; label: Localized; verified?: boolean };

export type ProjectPage = {
  slug: string;
  role: Localized;
  /** short versions written for the page (the case study has the long ones) */
  problem: Localized;
  solution: Localized;
  features: Localized[];
  results: Result[];
  techNotes: Localized;
  stack: string[];
  caseStudy: { ar: CaseStudy; en: CaseStudy };
  shots: Shot[];
  videos: Clip[];
  diagram: string | null;
};

export function loadProjectPage(slug: string): ProjectPage | null {
  const file = path.join(process.cwd(), "content", "projects", slug, "page.json");
  if (!/^[a-z0-9-]+$/.test(slug) || !fs.existsSync(file)) return null;
  return JSON.parse(fs.readFileSync(file, "utf8")) as ProjectPage;
}
